function check(input, actual, expected) {
  // Deep equality in which the order of object keys does not matter (array order does).
  const same = (x, y) => {
    if (Array.isArray(y)) return Array.isArray(x) && x.length === y.length && y.every((value, i) => same(x[i], value));
    if (y !== null && typeof y === 'object') {
      if (x === null || typeof x !== 'object' || Array.isArray(x)) return false;
      const keys = Object.keys(y);
      return Object.keys(x).length === keys.length && keys.every(key => Object.hasOwn(x, key) && same(x[key], y[key]));
    }
    return x === y;
  };
  return same(actual, expected);
}

