function validate(input) {
  const [obj] = input;
  if (obj === null || typeof obj !== 'object') return 'obj must be a JSON object or array.';
  for (const key of Object.keys(obj)) {
    if (typeof obj[key] !== 'string') return 'Every value of obj must be a string.';
    if (key === '__proto__' || obj[key] === '__proto__') return '"__proto__" cannot be a key or a value.';
  }
  if (JSON.stringify(obj).length > 100000) return 'Keep obj under 100,000 characters of JSON.';
  return null;
}

