function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  // A small pool of values makes repeated values (and so arrays in the answer) common.
  const poolSize = small ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 900);
  const pool = Array.from({ length: poolSize }, (_, i) => {
    const r = rand();
    return r < 0.4 ? String(Math.floor(rand() * 50)) : r < 0.5 ? '' : pick(['a', 'b', 'x', 'yes', 'no', 'v']) + i;
  });
  const count = small ? Math.floor(rand() * 7) : 1500 + Math.floor(rand() * 501);
  if (rand() < 0.4) return [Array.from({ length: count }, () => pick(pool))];
  const keyPool = ['a', 'b', 'c', 'd', 'x', 'y', 'id', '0', '1', '2', '10', '07'];
  const obj = {};
  for (let i = 0; i < count; i++) {
    const key = small ? pick(keyPool) : rand() < 0.3 ? String(Math.floor(rand() * 5000)) : 'k' + i;
    obj[key] = pick(pool);
  }
  return [obj];
}
